insert into reading_strategy_detail (strategy_slug, year_level, ku_verbatim, ks_verbatim) values ('visualising', '6', ARRAY['Knowledge of literary works can assist in making accurate predictions.','Narrative texts have many variations in their plot structures','Knowledge of different disciplines e.g science and technology), allow us to better understand texts.','Relationships among characters can be inferred using a range of sources.','Texts in many genres give us new insights into cultures of historical times.'], ARRAY['I can use my prior knowledge of genre, text structure and purpose to predict information, arguments, evidence and plotlines of texts.','I can predict if texts will contain specific literacy features such as plot twists, flashbacks, flashforwards or foreshadowing.','I can discuss my prior knowledge on a specific subject and how it relates to the text I have read.','I can identify the relationship between the characters and how these change based upon plots and interpretations.','I can explain what cultural and historical insights the text has provided to us and how.']);
insert into reading_strategy_detail (strategy_slug, year_level, ku_verbatim, ks_verbatim) values ('analysing', 'F', ARRAY['Narrative texts (fiction texts) tell stories and informative texts (non-fiction) give us information.','Why I have favourite books.','Fiction texts usually have drawn pictures, whereas non-fiction texts usually have photographs','Narratives texts usually have a beginning (characters, setting) problem and solution','Informative texts contain facts.'], ARRAY['I can identify some features of imaginary texts such as drawn pictures, family beginnings e.g once upon a time, A long, long time ago, familiar characters such as fairytale characters','I can identify some features of informative texts such as real photographs','I can identify some features of imaginary texts such as drawn pictures and familiar characters.','I can identify books which I enjoy','I can explain why I enjoy these books e.g because they are funny, because I like scary stories.','I can identify the beginning, problem and solution of the text.']);
insert into reading_strategy_detail (strategy_slug, year_level, ku_verbatim, ks_verbatim) values ('analysing', '1', ARRAY['Narrative persuasive and informative texts have similarities and differences.','Different text types of texts have different purposes.','Texts can have realistic or imaginary parts of a fiction texts.'], ARRAY['I can explain how texts are similar and how they are different.','I can identify the purpose of different text types.','I can identify the realistic and imaginary parts of a fiction text.']);
insert into reading_strategy_detail (strategy_slug, year_level, ku_verbatim, ks_verbatim) values ('analysing', '2', ARRAY['Texts are organised differently depending on their genre and purpose.','Texts use different language features depending on their purpose.','Different text types of texts have different purposes.','Language can be used to appreciate texts and provide reasons for preferences'], ARRAY['I can identify the structure and features of a text.','I can make connections between language features and their purpose.','I can identify the purpose of different text types using evidence to explain my reasoning E.g identify structure, Explaining text features, Types of vocabulary used e.g technical vocabulary found information texts.','I can use precise words and phrases to discuss what I liked about the text such as ''I liked how the author described the setting because …''','I can use words such as, ''preferred'' and ''enjoyed'' to describe what I liked about the text.']);
insert into reading_strategy_detail (strategy_slug, year_level, ku_verbatim, ks_verbatim) values ('analysing', '3', ARRAY['Texts with similar purposes can be created for different audiences.','Comparing and contrasting helps develop a deeper understanding of texts and topics.','Some texts will suit my purpose for reading them depending on their relevance.','Fiction texts can have realistic or fantasy elements'], ARRAY['I can identify the purpose and audience of the text using text clues such as age appropriate language, greater use of images rather than text or high level tier 3 vocabulary.','I can identify the similarities and differences between texts and ideas.','I can determine if a text was relevant for my purpose for reading.','I can identify if the text was realistic or fantasy fiction and explain my reasoning.']);
insert into reading_strategy_detail (strategy_slug, year_level, ku_verbatim, ks_verbatim) values ('analysing', '4', ARRAY['Different text types have typical stages and language features dependent on their purpose.','Fact and opinion','The author''s use of evidence supports arguments dependent on their strength.','Authors use techniques to help us navigate a text.'], ARRAY['I can identify the stages/features of different text types and discuss their purpose','I can identify the language features of different text types and discuss their purpose','I can identify how the author used techniques, such as headings, italics and bold text, to support navigation of specific texts','I can evaluate if the author''s use of evidence supporting their argument.','I can explain how author''s use different literary devices to add to the meaning of the text. (grammar, word choices, free verse, symbolism, personification, metaphor etc.)','I can discuss how the author made the text interesting or exciting.','Text types include: narratives, factual recounts, imaginative recounts, biographies, information reports, explanations, book talks, poetry and arguments for a particular purpose']);
insert into reading_strategy_detail (strategy_slug, year_level, ku_verbatim, ks_verbatim) values ('analysing', '5', ARRAY['Different text types have typical stages, phases and language features dependent on their purpose.','Author''s make texts more exciting, and engaging to hold the readers interest','Author''s use literary devices to shape the meaning of the text. (grammar, word choices, free verse, symbolism, personification, metaphor etc.)'], ARRAY['I can identify the stages, phases, and purposes, of a range of texts including: narratives, historical recounts, procedural recounts, causal explanations, discussions of alternative positions on an issue, information reports, reviews and types of poems','I can explain the devices used by the author to make the text interesting and engaging,','I can explain how useful the text was dependent on my purpose as a reader.','I can explain how author''s use different literary devices to add to the meaning of the text. (grammar, word choices, free verse, symbolism, personification, metaphor etc.)','I can identify examples of hybrid texts as well as the fictional and non-fiction elements of these texts.','I can evaluate if the text I am reading is relevant to my purpose for reading.','I can identify the mood of the text and discuss the purpose for this.']);
insert into reading_strategy_detail (strategy_slug, year_level, ku_verbatim, ks_verbatim) values ('analysing', '6', ARRAY['Author biases can influence the meaning and arguments of a text.','The text structures and language features of a text work together to meet the purpose of, engage and influence the audience.','Some texts may be more authentic than others for our purpose.'], ARRAY['I can identify words and phrases which show author''s bias towards a particular subject, idea/s or argument including literacy devices such as contradiction, paradox and allusion','I can evaluate if the author''s arguments or ideas are well supported.','I can explain how the text structure and language features engage or influence the audience.','I can explain how the text structure and language features meet the purpose of the text.','I can use other sources to evaluate the authenticity of a text (e.g. research and additional reading).']);
insert into reading_strategy_detail (strategy_slug, year_level, ku_verbatim, ks_verbatim) values ('critiquing', 'F', ARRAY['Narrative texts (fiction texts) tell stories and informative texts (non-fiction) give us information.','Why I have favourite books.','Fiction texts usually have drawn pictures, whereas non-fiction texts usually have photographs','Narratives texts usually have a beginning (characters, setting) problem and solution','Informative texts contain facts.'], ARRAY['I can identify some features of imaginary texts such as drawn pictures, family beginnings e.g once upon a time, A long, long time ago, familiar characters such as fairytale characters','I can identify some features of informative texts such as real photographs','I can identify some features of imaginary texts such as drawn pictures and familiar characters.','I can identify books which I enjoy','I can explain why I enjoy these books e.g because they are funny, because I like scary stories.','I can identify the beginning, problem and solution of the text.']);
