insert into reading_strategy_detail (strategy_slug, year_level, ku_verbatim, ks_verbatim) values ('questioning', '1', ARRAY['Narrative persuasive and informative texts have similarities and differences.','Different text types of texts have different purposes.','Texts can have realistic or imaginary parts of a fiction texts.'], ARRAY['I can explain how texts are similar and how they are different.','I can identify the purpose of different text types.','I can identify the realistic and imaginary parts of a fiction text.']);
insert into reading_strategy_detail (strategy_slug, year_level, ku_verbatim, ks_verbatim) values ('questioning', '2', ARRAY['Texts are organised differently depending on their genre and purpose.','Texts use different language features depending on their purpose.','Different text types of texts have different purposes.','Language can be used to appreciate texts and provide reasons for preferences'], ARRAY['I can identify the structure and features of a text.','I can make connections between language features and their purpose.','I can identify the purpose of different text types using evidence to explain my reasoning E.g identify structure, Explaining text features, Types of vocabulary used e.g technical vocabulary found information texts.','I can use precise words and phrases to discuss what I liked about the text such as ''I liked how the author described the setting because …''','I can use words such as, ''preferred'' and ''enjoyed'' to describe what I liked about the text.']);
insert into reading_strategy_detail (strategy_slug, year_level, ku_verbatim, ks_verbatim) values ('questioning', '3', ARRAY['Texts with similar purposes can be created for different audiences.','Comparing and contrasting helps develop a deeper understanding of texts and topics.','Some texts will suit my purpose for reading them depending on their relevance.','Fiction texts can have realistic or fantasy elements'], ARRAY['I can identify the purpose and audience of the text using text clues such as age appropriate language, greater use of images rather than text or high level tier 3 vocabulary.','I can identify the similarities and differences between texts and ideas.','I can determine if a text was relevant for my purpose for reading.','I can identify if the text was realistic or fantasy fiction and explain my reasoning.']);
insert into reading_strategy_detail (strategy_slug, year_level, ku_verbatim, ks_verbatim) values ('questioning', '4', ARRAY['Different text types have typical stages and language features dependent on their purpose.','Fact and opinion','The author''s use of evidence supports arguments dependent on their strength.','Authors use techniques to help us navigate a text.'], ARRAY['I can identify the stages/features of different text types and discuss their purpose','I can identify the language features of different text types and discuss their purpose','I can identify how the author used techniques, such as headings, italics and bold text, to support navigation of specific texts','I can evaluate if the author''s use of evidence supporting their argument.','I can explain how author''s use different literary devices to add to the meaning of the text. (grammar, word choices, free verse, symbolism, personification, metaphor etc.)','I can discuss how the author made the text interesting or exciting.','Text types include: narratives, factual recounts, imaginative recounts, biographies, information reports, explanations, book talks, poetry and arguments for a particular purpose']);
insert into reading_strategy_detail (strategy_slug, year_level, ku_verbatim, ks_verbatim) values ('questioning', '5', ARRAY['Different text types have typical stages, phases and language features dependent on their purpose.','Author''s make texts more exciting, and engaging to hold the readers interest','Author''s use literary devices to shape the meaning of the text. (grammar, word choices, free verse, symbolism, personification, metaphor etc.)'], ARRAY['I can identify the stages, phases, and purposes, of a range of texts including: narratives, historical recounts, procedural recounts, causal explanations, discussions of alternative positions on an issue, information reports, reviews and types of poems','I can explain the devices used by the author to make the text interesting and engaging,','I can explain how useful the text was dependent on my purpose as a reader.','I can explain how author''s use different literary devices to add to the meaning of the text. (grammar, word choices, free verse, symbolism, personification, metaphor etc.)','I can identify examples of hybrid texts as well as the fictional and non-fiction elements of these texts.','I can evaluate if the text I am reading is relevant to my purpose for reading.','I can identify the mood of the text and discuss the purpose for this.']);
insert into reading_strategy_detail (strategy_slug, year_level, ku_verbatim, ks_verbatim) values ('questioning', '6', ARRAY['Author biases can influence the meaning and arguments of a text.','The text structures and language features of a text work together to meet the purpose of, engage and influence the audience.','Some texts may be more authentic than others for our purpose.'], ARRAY['I can identify words and phrases which show author''s bias towards a particular subject, idea/s or argument including literacy devices such as contradiction, paradox and allusion','I can evaluate if the author''s arguments or ideas are well supported.','I can explain how the text structure and language features engage or influence the audience.','I can explain how the text structure and language features meet the purpose of the text.','I can use other sources to evaluate the authenticity of a text (e.g. research and additional reading).']);
insert into reading_strategy_detail (strategy_slug, year_level, ku_verbatim, ks_verbatim) values ('self_monitoring', 'F', ARRAY['What I read needs to make sense, sound right and look right.','I need to stop when what I have read does not make sense, sound right or look right.','Clues from the pictures and words can help me fix up my errors.'], ARRAY['I can stop when my reading does not make sense, sound right or look right. (Choose 1 to focus on for a series of lessons)','I can go back to the start of the sentence and re-read','I can fix up my error using picture or word clues and continue reading.']);
insert into reading_strategy_detail (strategy_slug, year_level, ku_verbatim, ks_verbatim) values ('self_monitoring', '1', ARRAY['When I read needs to make sense, sound right and look right.','I need to stop when what I have read does not make sense, sound right or look right.','Clues from the pictures and words can help me fix up my errors.','I need to think about what I am reading at all times.'], ARRAY['I can stop when my reading does not make sense, sound right or look right. (Choose 1 to focus on for a series of lessons)','I can fix up my errors using picture or word clues and continue reading.','I can ask myself "Do I understand what I have read?"','I can go back and re-read when I have lost meaning.','I can explain what I have read.']);
insert into reading_strategy_detail (strategy_slug, year_level, ku_verbatim, ks_verbatim) values ('self_monitoring', '2', ARRAY['To understand what I read I need to think about (monitor) what I am reading at all times.','To understand a text I need to re-read when my reading has lost meaning or doesn''t make sense.'], ARRAY['I can use a range of strategies to self correct and monitor my reading. E.g *letter sound knowledge *high frequency words *content knowledge *aware of text structure and features']);
insert into reading_strategy_detail (strategy_slug, year_level, ku_verbatim, ks_verbatim) values ('self_monitoring', '3', ARRAY['Self-monitoring when reading involves thinking about what is being read and using multiple sources to confirm meaning. These sources include language structure, illustrations, and diagrams.','Homographs are words that are spelt the same but have different meanings, and sometimes different pronunciations. Understanding them requires using context to determine which meaning is intended.','Homophones are words that sound the same but have different meanings and spellings.','Contractions are when two words are combined to make a new, shorter word. An apostrophe is used to show where the letters have been removed.'], ARRAY['I can self-monitor when reading by asking myself ''Does this make sense?''','I can use multiple sources in a text to check my understanding. Including rereading the sentence or passage, using the images, glossary, caption, knowledge of the topic etc.','I can use the context of the text to read homographs with accuracy.','I can use the spelling of homophones and the context of the text to read homophones with accuracy.','I can use my understanding of contractions to understand their meaning within the text.']);
insert into reading_strategy_detail (strategy_slug, year_level, ku_verbatim, ks_verbatim) values ('self_monitoring', '4', ARRAY['Readers actively monitor their reading, they check for meaning, recognise when something doesn''t make sense, and take corrective action.','Monitoring includes checking word recognition, syntax, meaning, and fluency.'], ARRAY['I can ask or think questions while reading (e.g., "What did I just read? Does that match what I expect? What might come next?")','I can pause during reading to check: "Does this make sense? Does it fit with what I''ve read so far?"','I can recognise when a reading error has changed meaning (for example, misreading a word, skipping a line, misunderstanding punctuation) and go back to correct it.','I can use multiple sources of information (semantic: meaning; syntactic: structure; graphophonic: letter-sound) to reassess a part of text when meaning is lost.','I can re-read or slow down when comprehension breaks down (word confusion, sentence complexity, unfamiliar vocabulary).']);
insert into reading_strategy_detail (strategy_slug, year_level, ku_verbatim, ks_verbatim) values ('self_monitoring', '5', ARRAY['Strategies can be used to repair meaning at the word, sentence and text level.','Literacy elements allow me to monitor and correct my reading.'], ARRAY['I can use a variety of strategies to self correct including re-reading, cross checking','I can utilise my knowledge of text structure and features to monitor and self correct']);
insert into reading_strategy_detail (strategy_slug, year_level, ku_verbatim, ks_verbatim) values ('self_monitoring', '6', ARRAY['Strategies can be used to repair meaning at the word, sentence and text level.','Literacy elements allow me to monitor and correct my reading.','Knowledge of tier 3 language can assist me to monitor understanding of texts with new information and idea.'], ARRAY['I can use a variety of strategies to self correct including re-reading, cross checking','I can utilise my knowledge of text structure and features to monitor and self correct']);
